// Generates data/illustration-pack/ — curated pre-A1 kid vocabulary illustrations.
//
// Run once (or to refresh): node scripts/build-illustration-pack.mjs
//
// Sources (license-clean for redistribution):
//   • Alphabet letter cards — CC0, generated by this script (simple SVG art).
//   • Noun pictures — Twemoji SVGs (CC-BY 4.0, https://github.com/twitter/twemoji).
//
// Attribution for Twemoji nouns is recorded in data/illustration-pack/manifest.json
// and docs/decisions.md (ADR 0016).

import { createWriteStream, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { get as httpsGet } from "node:https";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");
const PACK_DIR = join(ROOT, "data", "illustration-pack");
const IMAGES_DIR = join(PACK_DIR, "images");
const LETTERS_DIR = join(IMAGES_DIR, "letters");
const NOUNS_DIR = join(IMAGES_DIR, "nouns");
const MANIFEST_PATH = join(PACK_DIR, "manifest.json");

const STYLE = "kid-illustration";
const TWEMOJI_VERSION = "14.0.2";
const TWEMOJI_BASE = `https://cdn.jsdelivr.net/gh/twitter/twemoji@${TWEMOJI_VERSION}/assets/svg`;

/** Letter → phonics anchor noun → Twemoji codepoint (hex, no U+ prefix). */
const VOCAB = [
  ["a", "apple", "1f34e"],
  ["b", "ball", "26bd"],
  ["c", "cat", "1f431"],
  ["d", "dog", "1f436"],
  ["e", "egg", "1f95a"],
  ["f", "fish", "1f41f"],
  ["g", "goat", "1f410"],
  ["h", "hat", "1f3a9"],
  ["i", "ice", "1f9ca"],
  ["j", "jam", "1f353"],
  ["k", "kite", "1fa81"],
  ["l", "lion", "1f981"],
  ["m", "moon", "1f319"],
  ["n", "nest", "1fab3"],
  ["o", "orange", "1f34a"],
  ["p", "pig", "1f437"],
  ["q", "queen", "1f478"],
  ["r", "rabbit", "1f430"],
  ["s", "sun", "1f31e"],
  ["t", "tree", "1f333"],
  ["u", "umbrella", "1f302"],
  ["v", "van", "1f690"],
  ["w", "whale", "1f40b"],
  ["x", "box", "1f4e6"],
  ["y", "yarn", "1f9f6"],
  ["z", "zebra", "1f993"],
];

const LETTER_COLORS = [
  "#FFE566",
  "#FF9F43",
  "#FF6B6B",
  "#F368E0",
  "#A29BFE",
  "#74B9FF",
  "#55EFC4",
  "#81ECEC",
  "#FAB1A0",
  "#DFE6E9",
  "#FD79A8",
  "#FDCB6E",
  "#B2BEC3",
  "#00B894",
  "#E17055",
  "#6C5CE7",
  "#0984E3",
  "#00CEC9",
  "#F39C12",
  "#27AE60",
  "#8E44AD",
  "#3498DB",
  "#1ABC9C",
  "#E74C3C",
  "#9B59B6",
  "#2ECC71",
];

function download(url) {
  return new Promise((resolve, reject) => {
    httpsGet(url, (res) => {
      if (res.statusCode === 301 || res.statusCode === 302) {
        const location = res.headers.location;
        if (!location) {
          reject(new Error(`Redirect without location for ${url}`));
          return;
        }
        download(location).then(resolve, reject);
        return;
      }
      if (res.statusCode !== 200) {
        reject(new Error(`HTTP ${res.statusCode} for ${url}`));
        return;
      }
      const chunks = [];
      res.on("data", (chunk) => chunks.push(chunk));
      res.on("end", () => resolve(Buffer.concat(chunks)));
      res.on("error", reject);
    }).on("error", reject);
  });
}

function letterSvg(letter, fill) {
  const upper = letter.toUpperCase();
  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" role="img" aria-label="Letter ${upper}">
  <rect width="512" height="512" rx="48" fill="${fill}"/>
  <text x="256" y="340" font-size="280" font-family="system-ui, -apple-system, sans-serif" font-weight="700" text-anchor="middle" fill="#2d3436">${upper}</text>
</svg>
`;
}

async function writeLetterCards() {
  const entries = [];
  for (let i = 0; i < VOCAB.length; i++) {
    const [letter] = VOCAB[i];
    const file = `letters/${letter}.svg`;
    const outPath = join(IMAGES_DIR, file);
    writeFileSync(outPath, letterSvg(letter, LETTER_COLORS[i % LETTER_COLORS.length]));
    entries.push({
      key: letter,
      file,
      mimeType: "image/svg+xml",
      artSource: "letter-art",
      license: "CC0-1.0",
    });
  }
  return entries;
}

async function writeNounPictures() {
  const entries = [];
  for (const [, noun, codepoint] of VOCAB) {
    const file = `nouns/${noun}.svg`;
    const outPath = join(IMAGES_DIR, file);
    const url = `${TWEMOJI_BASE}/${codepoint}.svg`;
    const data = await download(url);
    writeFileSync(outPath, data);
    entries.push({
      key: noun,
      file,
      mimeType: "image/svg+xml",
      artSource: "twemoji",
      license: "CC-BY-4.0",
      twemojiCodepoint: codepoint,
    });
  }
  return entries;
}

async function main() {
  mkdirSync(LETTERS_DIR, { recursive: true });
  mkdirSync(NOUNS_DIR, { recursive: true });

  const [letterEntries, nounEntries] = await Promise.all([writeLetterCards(), writeNounPictures()]);

  const manifest = {
    version: 1,
    style: STYLE,
    createdAt: "2026-01-01T00:00:00.000Z",
    license: {
      summary: "Mixed CC0 (letter art) and CC-BY 4.0 (Twemoji noun pictures)",
      letters: {
        name: "CC0 1.0",
        note: "Simple alphabet letter cards generated by scripts/build-illustration-pack.mjs",
      },
      nouns: {
        name: "CC-BY 4.0",
        note: "Twemoji SVG assets (Twitter, Inc. and contributors)",
        url: "https://creativecommons.org/licenses/by/4.0/",
        source: `https://github.com/twitter/twemoji/tree/v${TWEMOJI_VERSION}`,
      },
    },
    entries: [...letterEntries, ...nounEntries],
  };

  writeFileSync(MANIFEST_PATH, `${JSON.stringify(manifest, null, 2)}\n`);
  console.log(
    `Wrote ${manifest.entries.length} illustration-pack entries to ${PACK_DIR.replace(ROOT + "/", "")}/`,
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
